-- SOCIAL-WEEKLY-CAPS-PROBE-1 (2026-11-03, pillar autonomy; agent_issues 1000610):
-- The 2026-10-27 LinkedIn pair was 5 h apart under a cap of 7 (the worker's spacing is 23 h).
-- The original probe's fixed 6 h threshold detected that incident but missed violations
-- between 6 h and the spacing required by a channel's configured effective cap.
-- The replacement reads the Buffer channel cap and attention-share settings, checks the
-- rolling weekly count and enforces the same cap-derived spacing as qnfo-social.
-- Prediction: the 7-day probe will flag any remaining under-spaced or over-cap Buffer posts
-- and return ok once the offending 2026-10-27 posts leave its window. Rollback restores the
-- original 6 h probe and alternate description.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'') IS NULL OR json_valid((SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'')) = 0 THEN ''pipeline_flags social_channel_caps is missing or not JSON'' WHEN COALESCE((SELECT MIN(gap_min) FROM (SELECT (julianday(substr(published_at, 1, 19)) - julianday(LAG(substr(published_at, 1, 19)) OVER (PARTITION BY platform ORDER BY published_at))) * 1440 AS gap_min FROM social_media_posts WHERE status = ''published'' AND platform <> ''buffer-substack'' AND published_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days''))), 99999) < 360 THEN ''two posts on one channel landed under 6 h apart, so the spacing that stands in for the cap is not holding'' ELSE ''ok'' END AS observed', window_note = '7 days: the spacing between consecutive published posts per channel (Substack Notes roll-ups excluded); the cap itself is read from pipeline_flags' WHERE control = 'social-weekly-caps'; UPDATE control_registry SET alternate_path = 'BSKY-SPACING-1 spacing and the channel drain spacing keep posts spread; the attention share steers inside the cap' WHERE control = 'social-weekly-caps';

UPDATE control_alternate_probes
SET probe_sql = 'WITH config AS (SELECT CASE WHEN json_valid((SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'')) THEN (SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'') ELSE ''{}'' END AS caps, CASE WHEN json_valid((SELECT value FROM ops_config WHERE key = ''attention_channel_share'')) AND julianday((SELECT updated_at FROM ops_config WHERE key = ''attention_channel_share'')) >= julianday(''now'', ''-3 days'') THEN (SELECT value FROM ops_config WHERE key = ''attention_channel_share'') ELSE ''{}'' END AS shares, COALESCE((SELECT CASE WHEN CAST(value AS REAL) BETWEEN 0 AND 1 THEN CAST(value AS REAL) END FROM pipeline_flags WHERE key = ''social_share_floor''), 0.5) AS floor), raw_posts AS (SELECT platform, published_at, CASE platform WHEN ''buffer-linkedin'' THEN ''linkedin'' WHEN ''buffer-mastodon'' THEN ''mastodon'' ELSE ''twitter'' END AS channel, CASE platform WHEN ''buffer-linkedin'' THEN CASE WHEN json_type(config.caps, ''$.linkedin'') IN (''integer'', ''real'') THEN MIN(21, MAX(0, CAST(json_extract(config.caps, ''$.linkedin'') AS INTEGER))) ELSE 7 END WHEN ''buffer-mastodon'' THEN CASE WHEN json_type(config.caps, ''$.mastodon'') IN (''integer'', ''real'') THEN MIN(21, MAX(0, CAST(json_extract(config.caps, ''$.mastodon'') AS INTEGER))) ELSE 14 END ELSE CASE WHEN json_type(config.caps, ''$.twitter'') IN (''integer'', ''real'') THEN MIN(21, MAX(0, CAST(json_extract(config.caps, ''$.twitter'') AS INTEGER))) ELSE 14 END END AS base_cap, LAG(published_at) OVER (PARTITION BY platform ORDER BY published_at) AS previous_at, COUNT(*) OVER (PARTITION BY platform) AS posts_7d FROM social_media_posts CROSS JOIN config WHERE status = ''published'' AND platform IN (''buffer-linkedin'', ''buffer-mastodon'', ''buffer-x'', ''buffer-twitter'') AND published_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')), effective_posts AS (SELECT raw_posts.*, CASE WHEN base_cap <= 0 THEN 0 ELSE MAX(1, CAST(base_cap * (config.floor + (1 - config.floor) * CASE WHEN json_type(config.shares, ''$.'' || channel) IN (''integer'', ''real'') THEN MIN(1, MAX(0, CAST(json_extract(config.shares, ''$.'' || channel) AS REAL))) ELSE 1 END) AS INTEGER)) END AS effective_cap FROM raw_posts CROSS JOIN config) SELECT ''ok'' AS expected, CASE WHEN (SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'') IS NULL OR json_valid((SELECT value FROM pipeline_flags WHERE key = ''social_channel_caps'')) = 0 THEN ''pipeline_flags social_channel_caps is missing or not JSON'' WHEN EXISTS (SELECT 1 FROM effective_posts WHERE effective_cap = 0) THEN ''posts exist on a Buffer channel whose effective weekly cap is zero'' WHEN EXISTS (SELECT 1 FROM effective_posts WHERE posts_7d > effective_cap) THEN ''published Buffer posts exceed a channel effective weekly cap in 7 days'' WHEN EXISTS (SELECT 1 FROM effective_posts WHERE previous_at IS NOT NULL AND CAST(strftime(''%s'', published_at) AS INTEGER) - CAST(strftime(''%s'', previous_at) AS INTEGER) < CAST(604800.0 / effective_cap AS INTEGER) - 3600) THEN ''consecutive Buffer posts violate the channel effective weekly-cap spacing'' ELSE ''ok'' END AS observed',
    window_note = '7 days: published Buffer channel posts, excluding Substack Notes; compare the rolling count and adjacent-post spacing with the channel cap after the current attention share and floor are applied',
    enabled = 1
WHERE control = 'social-weekly-caps';

UPDATE control_registry
SET alternate_path = 'Cap-derived spacing and weekly counts for each Buffer channel; attention share only lowers the cap'
WHERE control = 'social-weekly-caps';

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_copilot_issue_1000610',
  'A fixed six-hour probe threshold does not test the spacing required by each channel cap; the social alternate should be graded against the same effective cap as the posting paths',
  'SOCIAL-WEEKLY-CAPS-PROBE-1: update the read-only alternate probe to check each Buffer channel weekly count and cap-derived spacing, including the attention-share floor',
  'The 2026-10-27 LinkedIn pair was 5 h apart under a cap of 7, whose configured spacing is 23 h; qnfo-social CROSSPOST-CAP-1 now applies that spacing to cross-posts',
  'The 7-day control probe identifies posts beyond the configured weekly count or closer than the effective cap-derived spacing; it will pass after the known incident leaves the observation window',
  'One control_alternate_probes row and its control_registry alternate description',
  'Rollback in migrations/2026-11-03-social-weekly-caps-probe.sql restores the previous probe and alternate description',
  'The autonomy drill checks the same per-channel weekly cadence enforced by qnfo-social, rather than a fixed six-hour approximation',
  'Under-spaced or over-cap Buffer posts are detected by the next 6-hour drill; the probe returns to ok when the last known violating posts leave the 7-day window',
  'Reliability: the social weekly-cap alternate reports current evidence instead of missing violations between 6 h and the cap-derived interval',
  'SQLite migration regression suite: configured LinkedIn and X boundaries, weekly-count overrun, invalid configuration, and read-only probe'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'SOCIAL-WEEKLY-CAPS-PROBE-1:%');
